import { z } from "zod";
import { FLASH_LITE_31, GEMINI_SEED } from "@/lib/constants";
import {
  generateStructuredContent,
  type JsonSchema,
} from "@/lib/services/gemini";
import type { Logger } from "@/lib/logger";
import type { PositioningMatrixInput } from "../_lib/validation";

/**
 * Zod schema for 2-field × TR+EN positioning search queries generated by Gemini.
 * Fields: subject (odak/problem), actors (analiz birimi/aktörler).
 * Each field has 2 alternative queries (alt1, alt2) per language.
 */
export const generatedQueriesSchema = z.object({
  subjectTr_alt1: z
    .string()
    .min(2)
    .describe(
      "Çalışmanın odağı/problemi için 2-4 kelimelik Türkçe sorgu (alternatif 1)",
    ),
  subjectTr_alt2: z
    .string()
    .min(2)
    .describe(
      "Çalışmanın odağı/problemi için 2-4 kelimelik Türkçe sorgu (alternatif 2)",
    ),
  subjectEn_alt1: z
    .string()
    .min(2)
    .describe(
      "Çalışmanın odağı/problemi için 2-4 kelimelik İngilizce sorgu (alternatif 1)",
    ),
  subjectEn_alt2: z
    .string()
    .min(2)
    .describe(
      "Çalışmanın odağı/problemi için 2-4 kelimelik İngilizce sorgu (alternatif 2)",
    ),
  actorsTr_alt1: z
    .string()
    .min(2)
    .describe(
      "Analiz birimi/aktörler için 2-4 kelimelik Türkçe sorgu (alternatif 1)",
    ),
  actorsTr_alt2: z
    .string()
    .min(2)
    .describe(
      "Analiz birimi/aktörler için 2-4 kelimelik Türkçe sorgu (alternatif 2)",
    ),
  actorsEn_alt1: z
    .string()
    .min(2)
    .describe(
      "Analiz birimi/aktörler için 2-4 kelimelik İngilizce sorgu (alternatif 2)",
    ),
  actorsEn_alt2: z
    .string()
    .min(2)
    .describe(
      "Analiz birimi/aktörler için 2-4 kelimelik İngilizce sorgu (alternatif 2)",
    ),
});

/** Inferred TypeScript type for generated 2-field × TR+EN positioning queries. */
export type GeneratedQueries = z.infer<typeof generatedQueriesSchema>;

/** JSON Schema specification passed to Gemini structured outputs. */
export const generatedQueriesJsonSchema: JsonSchema = {
  type: "object",
  properties: {
    subjectTr_alt1: {
      type: "string",
      description:
        "Çalışmanın odağı ve problemi için 2-4 kelimelik Türkçe Meilisearch sorgusu (alternatif 1)",
    },
    subjectTr_alt2: {
      type: "string",
      description:
        "Çalışmanın odağı ve problemi için 2-4 kelimelik Türkçe Meilisearch sorgusu (alternatif 2)",
    },
    subjectEn_alt1: {
      type: "string",
      description:
        "Çalışmanın odağı ve problemi için 2-4 kelimelik İngilizce Meilisearch sorgusu (alternatif 1)",
    },
    subjectEn_alt2: {
      type: "string",
      description:
        "Çalışmanın odağı ve problemi için 2-4 kelimelik İngilizce Meilisearch sorgusu (alternatif 2)",
    },
    actorsTr_alt1: {
      type: "string",
      description:
        "Analiz birimi ve aktörler için 2-4 kelimelik Türkçe Meilisearch sorgusu (alternatif 1)",
    },
    actorsTr_alt2: {
      type: "string",
      description:
        "Analiz birimi ve aktörler için 2-4 kelimelik Türkçe Meilisearch sorgusu (alternatif 2)",
    },
    actorsEn_alt1: {
      type: "string",
      description:
        "Analiz birimi ve aktörler için 2-4 kelimelik İngilizce Meilisearch sorgusu (alternatif 1)",
    },
    actorsEn_alt2: {
      type: "string",
      description:
        "Analiz birimi ve aktörler için 2-4 kelimelik İngilizce Meilisearch sorgusu (alternatif 2)",
    },
  },
  required: [
    "subjectTr_alt1",
    "subjectTr_alt2",
    "subjectEn_alt1",
    "subjectEn_alt2",
    "actorsTr_alt1",
    "actorsTr_alt2",
    "actorsEn_alt1",
    "actorsEn_alt2",
  ],
  additionalProperties: false,
};

/**
 * Sanitizes a generated query string for strict Meilisearch full-text compatibility.
 * Removes boolean operators (OR, AND, NOT) and punctuation syntax characters that cause
 * unexpected literal term matching in Meilisearch.
 *
 * @param rawQuery - Raw query string generated by LLM.
 * @returns Cleaned query string optimized for Meilisearch keyword matching.
 */
export function sanitizeMeiliQuery(rawQuery: string): string {
  if (!rawQuery) return "";
  return rawQuery
    .replace(/\b(OR|AND|NOT)\b/gi, " ")
    .replace(/[+*?:^~={}[\]()"\\]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

import {
  POSITIONING_QUERIES_SYSTEM_INSTRUCTION,
  buildPositioningQueriesUserPrompt,
} from "@/lib/prompts";

/**
 * Generates 8 short academic search queries (2 matrix fields × TR + EN × 2 alternatives)
 * from the user's 4-field positioning matrix using Gemini Flash-Lite.
 *
 * Fields used: subjectProblem, analysisActors.
 * Methodology and theoreticalFramework are intentionally excluded.
 *
 * @param input - The validated 4-field positioning matrix input.
 * @param logger - Optional Logger instance for structured telemetry.
 * @returns Object containing 8 sanitized Meilisearch queries.
 */
export async function generatePositioningQueries(
  input: PositioningMatrixInput,
  logger?: Logger,
): Promise<GeneratedQueries> {
  const userPrompt = buildPositioningQueriesUserPrompt(input);

  const result = await generateStructuredContent<GeneratedQueries>(
    FLASH_LITE_31,
    POSITIONING_QUERIES_SYSTEM_INSTRUCTION,
    userPrompt,
    generatedQueriesJsonSchema,
    logger,
    {
      zodSchema: generatedQueriesSchema,
      payloadStage: "generate_positioning_queries",
      seed: GEMINI_SEED,
      thesisMatrix: input,
    },
  );

  return {
    subjectTr_alt1: sanitizeMeiliQuery(result.subjectTr_alt1),
    subjectTr_alt2: sanitizeMeiliQuery(result.subjectTr_alt2),
    subjectEn_alt1: sanitizeMeiliQuery(result.subjectEn_alt1),
    subjectEn_alt2: sanitizeMeiliQuery(result.subjectEn_alt2),
    actorsTr_alt1: sanitizeMeiliQuery(result.actorsTr_alt1),
    actorsTr_alt2: sanitizeMeiliQuery(result.actorsTr_alt2),
    actorsEn_alt1: sanitizeMeiliQuery(result.actorsEn_alt1),
    actorsEn_alt2: sanitizeMeiliQuery(result.actorsEn_alt2),
  };
}
